            .unwrap()
            .iter()
            .any(|warning| warning
                .as_str()
                .unwrap()
                .contains("rebuilt missing or stale CallSieve index before context"))
    );

    write(
        repo.path().join("src/auth/session.ts"),
        "import { tokenFor } from './token';\n\nexport function createSession(userId: string) {\n  return tokenFor(userId) + ':updated';\n}\n\nexport const refreshSession = () => createSession('demo');\n",
    );

use std::{
    collections::BTreeSet,
    fs,
    io::Write,
    path::{Path, PathBuf},
    process::{Command, Output, Stdio},
};

use serde_json::Value;

fn callsieve() -> PathBuf {
    PathBuf::from(env!("CARGO_BIN_EXE_callsieve"))
}

fn run(args: &[&str]) -> Output {
    Command::new(callsieve())
        .args(args)
        .output()
        .expect("failed to run callsieve")
}

fn run_with_stdin(args: &[&str], input: &str) -> Output {
    let mut child = Command::new(callsieve())
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("failed to run callsieve");
    child
        .stdin
        .as_mut()
        .expect("stdin should be piped")
        .write_all(input.as_bytes())
        .expect("failed to write hook input");
    child
        .wait_with_output()
        .expect("failed to collect callsieve output")
}

fn json(output: &Output) -> Value {
    assert!(
        output.status.success(),
        "command failed\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("stdout should be valid JSON")
}

fn json_allow_failure(output: &Output) -> Value {
    serde_json::from_slice(&output.stdout).expect("stdout should be valid JSON")
}

fn estimated_json_tokens(value: &Value) -> usize {
    serde_json::to_string(value).unwrap().len().div_ceil(4)
}

fn context_stats_tokens(stats: &Value) -> Option<u64> {
    stats
        .get("t")
        .or_else(|| stats.get("tokens"))
        .or_else(|| stats.get("estimated_tokens"))
        .and_then(Value::as_u64)
}

fn context_stats_budget(stats: &Value) -> Option<u64> {
    stats
        .get("b")
        .or_else(|| stats.get("budget"))
        .or_else(|| stats.get("token_budget"))
        .and_then(Value::as_u64)
}

fn context_stats_local_field(stats: &Value, compact: &str, legacy: &str) -> Option<u64> {
    stats
        .get("local")
        .and_then(|local| local.get(compact).or_else(|| local.get(legacy)))
        .and_then(Value::as_u64)
}

fn read_first_file_path(file: &Value) -> Option<&str> {
    file.get("f")
        .or_else(|| file.get("file"))
        .and_then(Value::as_str)
}

fn read_first_symbols(file: &Value) -> Option<&Vec<Value>> {
    file.get("sy")
        .or_else(|| file.get("symbols"))
        .and_then(Value::as_array)
}

fn read_first_symbol_name(symbol: &Value) -> Option<&str> {
    symbol
        .get("n")
        .or_else(|| symbol.get("name"))
        .and_then(Value::as_str)
        .or_else(|| {
            symbol
                .as_array()
                .and_then(|items| items.first())
                .and_then(Value::as_str)
        })
}

fn read_first_symbol_kind(symbol: &Value) -> Option<&str> {
    let kind = symbol
        .get("k")
        .or_else(|| symbol.get("kind"))
        .and_then(Value::as_str)
        .or_else(|| {
            let items = symbol.as_array()?;
            items
                .get(3)
                .or_else(|| items.get(2).filter(|value| value.is_string()))
                .and_then(Value::as_str)
        })?;
    Some(expand_compact_symbol_kind(kind))
}

fn expand_compact_symbol_kind(kind: &str) -> &str {
    match kind {
        "cl" => "class",
        "m" => "method",
        "if" => "interface",
        "t" => "type",
        "s" => "struct",
        "e" => "enum",
        "tr" => "trait",
        "im" => "impl",
        "c" => "constant",
        "mod" => "module",
        "mac" => "macro",
        "cmp" => "component",
        _ => kind,
    }
}

fn read_first_symbol_line_value(symbol: &Value) -> Option<&Value> {
    symbol
        .get("l")
        .or_else(|| symbol.get("line"))
        .or_else(|| symbol.get("ls"))
        .or_else(|| symbol.get("lines"))
        .or_else(|| symbol.as_array().and_then(|items| items.get(1)))
}

fn read_first_impact(file: &Value) -> Option<&Value> {
    file.get("i").or_else(|| file.get("impact"))
}

fn read_first_impact_risk(impact: &Value) -> Option<&str> {
    impact
        .get("r")
        .or_else(|| impact.get("risk"))
        .and_then(Value::as_str)
        .or_else(|| {
            impact
                .as_array()
                .and_then(|items| items.first())
                .and_then(Value::as_str)
        })
}

fn read_first_impact_tests(impact: &Value) -> Vec<String> {
    if let Some(tests) = impact.get("t").or_else(|| impact.get("tests")) {
        if let Some(test) = tests.as_str() {
            return vec![test.to_string()];
        }
        return tests
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(str::to_string)
            .collect();
    }
    let Some(test_value) = impact.as_array().and_then(|items| items.get(1)) else {
        return Vec::new();
    };
    if let Some(test) = test_value.as_str() {
        return vec![test.to_string()];
    }
    test_value
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
        .map(str::to_string)
        .collect()
}

fn read_first_impact_tests_for_context(context: &Value, impact: &Value) -> Vec<String> {
    fn resolve_test_ref(context: &Value, value: &Value) -> Option<String> {
        if let Some(path) = value.as_str() {
            return Some(path.to_string());
        }
        let index = value
            .as_u64()
            .and_then(|index| usize::try_from(index).ok())?;
        context
            .get("read_first")
            .and_then(Value::as_array)
            .and_then(|files| files.get(index))
            .and_then(read_first_file_path)
            .map(str::to_string)
    }

    if let Some(tests) = impact.get("t").or_else(|| impact.get("tests")) {
        if let Some(test) = resolve_test_ref(context, tests) {
            return vec![test];
        }
        return tests
            .as_array()
            .into_iter()
            .flatten()
            .filter_map(|value| resolve_test_ref(context, value))
            .collect();
    }

#[derive(Debug, Clone, Copy, Eq, PartialEq)]
pub enum QueryKind {
    Identifier,
    NaturalLanguage,
}

#[cfg(feature = "embed")]
pub const IDENTIFIER_LEXICAL_WEIGHT: f64 = 0.85;
#[cfg(feature = "embed")]
pub const IDENTIFIER_SEMANTIC_WEIGHT: f64 = 0.15;
#[cfg(feature = "embed")]
pub const NATURAL_LANGUAGE_LEXICAL_WEIGHT: f64 = 0.40;
#[cfg(feature = "embed")]
pub const NATURAL_LANGUAGE_SEMANTIC_WEIGHT: f64 = 0.60;

const SYMBOL_LOOKUP_INTENT: &[&str] = &[
    "symbol",
    "symbols",
    "function",
    "functions",
    "class",
    "classes",
    "method",
    "methods",
    "struct",
    "trait",
    "enum",
    "impl",
    "definition",
    "definitions",
];

pub fn query_kind(task: &str, query_tokens: &[String]) -> QueryKind {
    if has_raw_identifier_signal(task) || has_symbol_lookup_intent(query_tokens) {
        QueryKind::Identifier
    } else {
        QueryKind::NaturalLanguage
    }
}

impl QueryKind {
    #[cfg(feature = "embed")]
    pub fn weights(self) -> (f64, f64) {
        match self {
            Self::Identifier => (IDENTIFIER_LEXICAL_WEIGHT, IDENTIFIER_SEMANTIC_WEIGHT),
            Self::NaturalLanguage => (
                NATURAL_LANGUAGE_LEXICAL_WEIGHT,
                NATURAL_LANGUAGE_SEMANTIC_WEIGHT,
            ),
        }
    }

    #[cfg(feature = "embed")]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Identifier => "identifier",
            Self::NaturalLanguage => "natural_language",
        }
    }

    #[cfg(feature = "embed")]
    pub fn cosine_floor(self) -> f32 {
        match self {
            Self::NaturalLanguage => 0.10,
            Self::Identifier => 0.25,
        }
    }
}

fn has_symbol_lookup_intent(query_tokens: &[String]) -> bool {
    query_tokens
        .iter()
        .any(|token| SYMBOL_LOOKUP_INTENT.contains(&token.as_str()))
}

fn has_raw_identifier_signal(task: &str) -> bool {
    let words: Vec<&str> = task.split_whitespace().collect();
    for word in &words {
        let trimmed = trim_token(word);
        if trimmed.contains("::")
            || trimmed.contains("->")
            || looks_like_path(trimmed)
            || looks_like_dotted_identifier(trimmed)
            || looks_like_camel_case(trimmed)
            || looks_like_snake_case(trimmed)
            || looks_like_screaming_case(trimmed)
        {
            return true;
        }
    }

    words.len() <= 2
        && words
            .iter()
            .any(|word| looks_symbol_shaped(trim_token(word)))
}

fn trim_token(token: &str) -> &str {
    token.trim_matches(|c: char| {
        c.is_ascii_punctuation() && !matches!(c, '_' | '-' | '.' | '/' | ':' | '>')
    })
}

fn looks_symbol_shaped(token: &str) -> bool {
    !token.is_empty()
        && token
            .chars()
            .next()
            .is_some_and(|c| c == '_' || c.is_ascii_alphabetic())
        && token.chars().all(|c| c == '_' || c.is_ascii_alphanumeric())
}

fn looks_like_path(token: &str) -> bool {
    token.contains('/')
        && token
            .rsplit('/')
            .next()
            .is_some_and(|name| name.contains('.') || looks_symbol_shaped(name))
}

fn looks_like_dotted_identifier(token: &str) -> bool {
    let parts: Vec<&str> = token.split('.').collect();
    parts.len() >= 2 && parts.iter().all(|part| looks_symbol_shaped(part))
}

fn looks_like_camel_case(token: &str) -> bool {
    let has_lower = token.chars().any(|c| c.is_ascii_lowercase());
    let has_upper_after_first = token.chars().skip(1).any(|c| c.is_ascii_uppercase());
    has_lower && has_upper_after_first && looks_symbol_shaped(token)
}

fn looks_like_snake_case(token: &str) -> bool {
    token.contains('_')
        && token.chars().any(|c| c.is_ascii_lowercase())
        && token.split('_').filter(|part| !part.is_empty()).count() >= 2
        && looks_symbol_shaped(token)
}

fn looks_like_screaming_case(token: &str) -> bool {
    token.contains('_')
        && token.chars().any(|c| c.is_ascii_alphabetic())
        && token
            .chars()
            .filter(|c| c.is_ascii_alphabetic())
            .all(|c| c.is_ascii_uppercase())
        && looks_symbol_shaped(token)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::query::ranker;

    #[test]
    fn classifies_identifier_signals_from_raw_task() {
        let cases = [
            "Session::resolve_redirects",
            "request.url",
            "src/auth/session.ts",
            "tokenFor",
            "token_for",
            "CALLSIEVE_EMBEDDINGS",
            "symbol createSession",
        ];
        for case in cases {
            let tokens = ranker::query_tokens(case);
            assert_eq!(query_kind(case, &tokens), QueryKind::Identifier, "{case}");
        }
    }

    #[test]
    fn classifies_natural_language_tasks() {
        let task = "fix redirect handling when location header is relative";
        let tokens = ranker::query_tokens(task);
        assert_eq!(query_kind(task, &tokens), QueryKind::NaturalLanguage);
    }

    #[test]
    fn reads_raw_casing_not_only_normalized_tokens() {
        let raw = "change tokenFor behavior";
        let lower = "change token for behavior";
        let lower_tokens = ranker::query_tokens(lower);
        assert_eq!(query_kind(raw, &lower_tokens), QueryKind::Identifier);
        assert_eq!(query_kind(lower, &lower_tokens), QueryKind::NaturalLanguage);
    }
}
